"""One preregistered confirmation using exactly the first measured executable."""
import base64,json,os,subprocess,time,traceback,statistics
from prepare_vco1_portable import ROOT,sha,write
from joint_cycles_analysis import require
def main():
    old_name='evidence/voice_schur_refined_chainbench01.json';old=json.loads((ROOT/old_name).read_text(encoding='utf8'));require(old['passed'] and old['utility_passed'] and 1<old['median_paired_speedup']<=1.10,'marginal utility confirmation rule');cmd=old['commands'][1]['command'];exe=cmd[0];packet=cmd[1];work=ROOT/'references-local/schur-refined-chainconfirm01';require(not work.exists(),'exclusive confirmation');work.mkdir();sources={n:sha(ROOT/n) for n in ['tools/confirm_schur_chain.py',old_name,'tools/dynamic_schur_chain_solver.rs','tools/joint_schur_chain_kernel.rs','tools/schur_chain_bench.rs','docs/SCHUR_CADENA_PROTOCOLO.md']};private={n:sha(ROOT/n) for n in [__import__('pathlib').Path(exe).relative_to(ROOT).as_posix(),__import__('pathlib').Path(packet).relative_to(ROOT).as_posix(),__import__('pathlib').Path(cmd[2]).relative_to(ROOT).as_posix()]};require(private[__import__('pathlib').Path(exe).relative_to(ROOT).as_posix()]==next(f['sha256'] for f in old['outputs'] if f['path'].endswith('run.exe')),'same executable');commands=[];r=dict(passed=False,source_sha256=sources,private_used_sha256=private,new_compilation=False,same_executable=True);env=os.environ.copy();env['PATH']='C:/msys64/mingw64/bin;C:/msys64/ucrt64/bin;'+env['PATH']
    def run():
        t=time.perf_counter();q=subprocess.run([exe,packet,str(work/'roots.txt')],cwd=ROOT,env=env,capture_output=True,text=True,encoding='utf8',timeout=600,creationflags=subprocess.CREATE_NO_WINDOW);out=dict(command=[exe,packet,str(work/'roots.txt')],exit_code=q.returncode,stdout=q.stdout,stderr=q.stderr,wall_s=time.perf_counter()-t);commands.append(out);return out
    try:
        q=run()
        if q['exit_code']:run();require(False,'confirmation native rejection')
        lines=q['stdout'].splitlines();rounds=[list(map(int,x.split(',')[1:])) for x in lines if x.startswith('ROUND,')];require(len(rounds)==5 and [x[0] for x in rounds]==list(range(5)) and lines[-1]=='PASSED,84,5,reconstructed_candidate_gates','same five-round scope');require((work/'roots.txt').read_bytes()==__import__('pathlib').Path(cmd[2]).read_bytes(),'same roots');speed=statistics.median(x[1]/x[2] for x in rounds);r.update(passed=True,rounds=rounds,speedups=[x[1]/x[2] for x in rounds],median_paired_speedup=speed,utility_passed=speed>1,full_trajectory_admitted=False)
    except Exception:r['failure']=traceback.format_exc();r['failed_source_base64']={n:base64.b64encode((ROOT/n).read_bytes()).decode() for n in sources}
    r.update(commands=commands,source_sha256_after={n:sha(ROOT/n) for n in sources},private_used_sha256_after={n:sha(ROOT/n) for n in private},outputs=[dict(path=p.relative_to(ROOT).as_posix(),sha256=sha(p),bytes=p.stat().st_size) for p in work.iterdir() if p.is_file()]);require(sources==r['source_sha256_after'] and private==r['private_used_sha256_after'],'stable confirmation');write('evidence/voice_schur_refined_chainconfirm01.json',r);print('SCHUR_INPLACE_CONFIRM',r['passed'],r.get('median_paired_speedup'),r.get('utility_passed'),r.get('failure',''),flush=True)
if __name__=='__main__':main()
